// Video is generated by the agent through the ComfyUI MCP server; this CLI only
// records the selection and checks that the configured ComfyUI target answers.

export async function probeComfy(url, { fetchImpl = fetch, timeoutMs = 5000 } = {}) {
    const response = await fetchImpl(new URL('system_stats', url.replace(/\/?$/, '/')), { signal: AbortSignal.timeout(timeoutMs) });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const body = await response.json();
    return { version: body?.system?.comfyui_version || '' };
}

export default {
    id: 'comfy-mcp',
    task: 'video',
    label: 'ComfyUI MCP（非 API MiniMax H3 模板）',
    guide: 'providers/comfy-mcp.md',
    ledgerProviders: ['comfy.run_template', 'comfy.run_workflow', 'comfy.fetch_outputs', 'comfy.generate_image'],
    testedVersion: 'comfy-mcp 0.10.0',
    agentOnly: true,
    execution: 'agent',
    capabilities: ['text-to-video', 'image-to-video', 'audio-driven-video', 'pose-reference-video', 'multi-reference-video'],
    publicSettings: ['url'],
    fields: { url: { env: 'COMFYUI_URL', type: 'url' } },
    async doctor(settings, { fetchImpl }) {
        if (!settings.url) {
            return { ready: false, version: '', hint: '未配置 COMFYUI_URL 或 media.video.url；Agent 仍需自行注册 comfy-mcp。' };
        }
        try {
            const { version } = await probeComfy(settings.url, { fetchImpl });
            return { ready: true, version: version ? `ComfyUI ${version}` : '', hint: '' };
        } catch (error) {
            return { ready: false, version: '', hint: `ComfyUI 目标不可达: ${error.message}` };
        }
    },
};
